def clean(t):
  for a,b in LEX:t=t.replace(a,b)
  t=re.sub(r'\(\s*(\{\{\d+\}\})\s*\)',r'(\1)',t)
  t=re.sub(r'(\{\{\d+\}\})\s+그리고\.\s+(\{\{\d+\}\})',r'\1와 \2',t)
  t=re.sub(r'(\{\{\d+\}\})\s+및\.\s+(\{\{\d+\}\})',r'\1 및 \2',t)
  t=re.sub(r'(\{\{\d+\}\})\s+또는\.\s+(\{\{\d+\}\})',r'\1 또는 \2',t)
  t=t.replace('그리고.','그리고').replace('및.','및').replace('with with','with')
  t=re.sub(r'(\{\{\d+\}\})\s+([,.;:])',r'\1\2',t)
  t=re.sub(r'\b(?:a|an)\s+(\{\{\d+\}\})',r'\1',t)
  t=re.sub(r'(\{\{\d+\}\})\s+s\b',r'\1',t)
  t=re.sub(r'\(\s+','(',t);t=re.sub(r'\s+\)',')',t)
  t=re.sub(r'식\s*\(\s*\)','식',t);t=re.sub(r'그림\s*\(\s*\)','그림',t)
  t=re.sub(r'\b([가-힣A-Za-z][가-힣A-Za-z0-9_-]{1,20})\s+\1\b',r'\1',t)
  t=re.sub(r'[・]{3,}','',t);t=re.sub(r'\s+([,.!?;:])',r'\1',t);t=re.sub(r'\s{2,}',' ',t).strip()
  t=t.replace('분포로부터의 샘플링','분포에서의 샘플링').replace('분포로부터 샘플링','분포에서 샘플링').replace('분포로부터 샘플을','분포에서 샘플을')
  return t
for ch in range(3,9):
  for p in sorted((ROOT/f"ch{ch:02d}").glob("*.ko.json")):
    d=json.loads(p.read_text(encoding="utf8"));changed=False
    if p.name not in REVIEWED:
      for uid,t in list(d.get("translations",{}).items()):
        nt=clean(t)
        if nt!=t:d["translations"][uid]=nt;changed=True
      for i,t in enumerate(d.get("footnotes",[])):
        nt=clean(t)
        if nt!=t:d["footnotes"][i]=nt;changed=True
    key=p.stem.replace(".ko","")
    for (fk,uid),txt in FIX.items():
      if fk==key and uid in d.get("translations",{}):
        old=d["translations"][uid]
        if sorted(re.findall(r'\{\{\d+\}\}',old))!=sorted(re.findall(r'\{\{\d+\}\}',txt)):
          raise SystemExit(f"token mismatch {fk}/{uid}")
        if old!=txt:d["translations"][uid]=txt;changed=True
    if changed:p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+"\n",encoding="utf8")
print(json.dumps({"postedit":"done","manualOverrides":len(FIX)},ensure_ascii=False))
